sys_script_fix.script:
// ==========================
// STEP 1: Recompute UC points
// ==========================
var util = new CertPointsUtil();

var ucGR = new GlideRecord('x_kp101_kpmg_res_0_user_certification');
ucGR.query();

var ucCount = 0;

while (ucGR.next()) {

    var cert = ucGR.certificate.getRefRecord();
    if (!cert) continue;

    var points = util.getPoints(
        cert,
        ucGR.getValue('date_taken'),
        ucGR.getValue('resource')
    );

    // Only update if changed (optimization)
    if (ucGR.points_accrued != points) {
        ucGR.points_accrued = points;
        ucGR.update();
        ucCount++;
    }
}

gs.info('UC recalculated: ' + ucCount);


// ==========================
// STEP 2: Reset CU totals
// ==========================
var cuGR = new GlideRecord('x_kp101_kpmg_res_0_resource_profile');
cuGR.query();

while (cuGR.next()) {
    cuGR.certification_points = 0;
    cuGR.update();
}

gs.info('CU reset complete');


// ==========================
// STEP 3: Rebuild CU totals
// ==========================
var agg = new GlideAggregate('x_kp101_kpmg_res_0_user_certification');
agg.addAggregate('SUM', 'points_accrued');
agg.groupBy('resource'); // this is CU sys_id
agg.query();

var cuCount = 0;

while (agg.next()) {

    var cuSysId = agg.getValue('resource'); // THIS IS CU RECORD
    var total = parseInt(agg.getAggregate('SUM', 'points_accrued'), 10) || 0;

    var cu = new GlideRecord('x_kp101_kpmg_res_0_resource_profile');
    if (cu.get(cuSysId)) {

        cu.certification_points = total;
        cu.update();
        cuCount++;
    }
}

gs.info('CU rebuilt: ' + cuCount);
